constructor(api: ApiConfig, opts: ApiClientOptions = {}) {
  // Strip trailing slashes so a path join never produces a double '//'.
  this.baseUrl = (api.baseUrl || '').replace(/\/+$/, '');
  this.headers = { 'Content-Type': 'application/json' };
  // Bearer + APIM subscription headers are both optional and additive.
  if (api.bearerToken) this.headers['Authorization'] = `Bearer ${api.bearerToken}`;
  if (api.subscriptionKey) this.headers['Ocp-Apim-Subscription-Key'] = api.subscriptionKey;
  this.retries = opts.retries ?? 4; // defaults: 4 attempts, 1500ms linear backoff, 120s.
  this.backoffMs = opts.backoffMs ?? 1500;
  this.timeoutMs = opts.timeoutMs ?? 120000;
}

async request<T = unknown>(method: HttpMethod, path: string, body?: unknown, opts: RequestOptions = {}): Promise<ApiResponse<T>> {
  const url = this.resolve(path);
  const retries = opts.retries ?? this.retries;
  // Math.max(1, retries) guarantees at least one attempt even if retries is 0.
  for (let attempt = 0; attempt < Math.max(1, retries); attempt++) {
    try {
      const res = await this.doFetch(url, { method, headers: this.headers, body: /* ... */ undefined });
      const raw = await res.text();
      // Any HTTP status (incl. 4xx/5xx) is a SUCCESS here — return it to assert on.
      return { code: res.status, raw, request: { method, url, body } /* ... */ } as ApiResponse<T>;
    } catch (err) {
      // Only a THROWN fetch retries; linear backoff, and only if attempts remain.
      if (attempt < retries - 1) await sleep(this.backoffMs * (attempt + 1));
    }
  }
  // Every attempt threw: return a sentinel code:0 result, never an uncaught throw.
  return { code: 0, raw: `fetch failed: ...`, request: { method, url, body } } as ApiResponse<T>;
}

export function step(resp: ApiResponse, does: string, verdict: Verdict = 'info', respOverride?: unknown): EvidenceStep {
  const q = resp.request;
  // Stringify the request body only when present: object->JSON, string as-is, null->''.
  const bodyStr = q.body == null ? '' : typeof q.body === 'string' ? q.body : JSON.stringify(q.body);
  return {
    kind: 'api', // tags the panel so the report builder colours it as API evidence.
    does: does || '',
    req: `${q.method} ${q.url}`.trim(),
    body: trim(bodyStr, 800), // cap at 800 chars so a huge payload can't bloat the report.
    code: resp.code,
    // respOverride lets an assertion show its comparison string instead of the raw body.
    resp: trim(respOverride !== undefined ? respOverride : resp.raw, 800),
    verdict,
  };
}

export function expectStatus(resp: ApiResponse, expected: number | number[], does?: string): EvidenceStep {
  // Accept one code or many; normalize to a list so includes() works either way.
  const list = Array.isArray(expected) ? expected : [expected];
  const ok = list.includes(resp.code); // pass if the actual status is any expected one.
  const label = does || `Expect status ${list.join(' or ')}`;
  // respOverride writes real-vs-expected into the panel (e.g. -> 500 (expected 201)).
  return step(resp, label, ok ? 'pass' : 'fail', `→ ${resp.code} (expected ${list.join('|')})`);
}

export async function probe(name: string, client: ApiClient, fn: (ctx: ProbeContext) => Promise<void> | void): Promise<AgentResult<{ probe: string }>> {
  const steps: EvidenceStep[] = [];
  // Collectors all funnel into the one local steps[]; the body just calls them.
  const ctx: ProbeContext = { client, add: s => steps.push(s), step: (...a) => steps.push(step(...a)), expectStatus: (...a) => steps.push(expectStatus(...a)) } as ProbeContext;
  try {
    await fn(ctx);
  } catch (err) { // an unexpected throw becomes a failing step, not a crashed run.
    steps.push({ kind: 'note', does: `probe "${name}" threw`, resp: String(err), verdict: 'fail' });
  }
  // ok iff nothing failed; the whole probe rolls up into one composable AgentResult.
  const failures = steps.filter(s => s.verdict === 'fail').length;
  return { agent: `api-probe:${name}`, ok: failures === 0, summary: `${name}: ${steps.length} step(s), ${failures} failing`, data: { probe: name }, steps };
}
